"""Order reconciliation, spec-v1 contract.

Pure functions only: parses CSV strings, uses Decimal fixed-point,
outputs integer cents. No file/network/process access.
"""

import csv
import io
import json
from decimal import Decimal, InvalidOperation

_ORDER_FIELDS = ["order_id", "customer", "amount", "status", "created_at"]
_REFUND_FIELDS = ["refund_id", "order_id", "amount"]


def _valid_amount_text(text):
    """Return True if text is digits with at most two decimal places."""
    if not text:
        return False
    if "." in text:
        parts = text.split(".")
        if len(parts) != 2:
            return False
        whole, frac = parts
        if not whole.isdigit() or not frac.isdigit() or len(frac) > 2:
            return False
    else:
        if not text.isdigit():
            return False
    return True


def _parse_amount_cents(raw):
    """Return integer cents for a non-negative, <=2-decimal amount string.

    Rejects negatives, NaN/Infinity, and more than two decimal places.
    Uses Decimal (never float * 100).
    """
    if raw is None:
        raise ValueError("missing amount")
    text = raw.strip()
    if not _valid_amount_text(text):
        raise ValueError("invalid amount: %r" % (raw,))
    try:
        value = Decimal(text)
    except InvalidOperation:
        raise ValueError("invalid amount: %r" % (raw,))
    cents = value * Decimal(100)
    if cents != cents.to_integral_value():
        raise ValueError("amount has more than two decimals: %r" % (raw,))
    return int(cents.to_integral_value())


def _read_rows(csv_text, expected_fields, kind):
    """Parse a CSV string into a list of dicts keyed by expected fields.

    Returns [] for empty input or header-only input.
    """
    if csv_text is None:
        raise ValueError("missing %s csv" % kind)
    if csv_text == "":
        return []
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        return []
    header = [h.strip() for h in header]
    if header != expected_fields:
        raise ValueError("bad %s header: %r" % (kind, header))
    rows = []
    for line in reader:
        if not line or (len(line) == 1 and line[0].strip() == ""):
            continue  # skip blank lines
        if len(line) != len(expected_fields):
            raise ValueError("bad %s row: %r" % (kind, line))
        rows.append({k: v.strip() for k, v in zip(expected_fields, line)})
    return rows


def _dedupe(rows, id_field, kind):
    """Deduplicate rows by id: exact duplicates collapse; conflicts raise."""
    seen = {}
    unique = []
    for row in rows:
        key = row[id_field]
        if key in seen:
            if seen[key] != row:
                raise ValueError(
                    "conflicting %s rows for id %r" % (kind, key)
                )
            continue  # exact duplicate, count once
        seen[key] = row
        unique.append(row)
    return unique


def reconcile(orders_csv, refunds_csv, policy="v1", cutoff=None):
    """Reconcile orders and refunds per the v1 contract.

    Returns {"orders": [...], "customers": [...], "totals": {...}} with
    all money as integer cents. Raises ValueError on invalid data.
    """
    if policy != "v1":
        raise ValueError("unsupported policy: %r" % (policy,))
    # cutoff is reserved for future policies; v1 ignores it.
    _ = cutoff

    order_rows = _dedupe(
        _read_rows(orders_csv, _ORDER_FIELDS, "orders"), "order_id", "order"
    )
    refund_rows = _dedupe(
        _read_rows(refunds_csv, _REFUND_FIELDS, "refunds"), "refund_id", "refund"
    )

    orders = {}
    for row in order_rows:
        status = row["status"]
        if status not in ("paid", "cancelled"):
            raise ValueError("unknown order status: %r" % (status,))
        if not row["order_id"] or not row["customer"]:
            raise ValueError("empty order_id or customer")
        paid_cents = _parse_amount_cents(row["amount"])  # validates amount
        orders[row["order_id"]] = {
            "order_id": row["order_id"],
            "customer": row["customer"],
            "status": status,
            "paid_cents": paid_cents,
        }

    refund_cents_by_order = {oid: 0 for oid in orders}
    for row in refund_rows:
        oid = row["order_id"]
        if not row["refund_id"]:
            raise ValueError("empty refund_id")
        order = orders.get(oid)
        if order is None:
            raise ValueError("refund %r for unknown order %r"
                             % (row["refund_id"], oid))
        if order["status"] != "paid":
            raise ValueError("refund %r for cancelled order %r"
                             % (row["refund_id"], oid))
        amount = _parse_amount_cents(row["amount"])
        refund_cents_by_order[oid] += amount
        if refund_cents_by_order[oid] > order["paid_cents"]:
            raise ValueError("refunds exceed paid amount for order %r" % (oid,))

    result_orders = []
    customers_total = {}
    totals = {"paid_cents": 0, "refund_cents": 0, "net_cents": 0}
    for oid in sorted(orders):
        order = orders[oid]
        if order["status"] != "paid":
            continue
        refund = refund_cents_by_order[oid]
        net = order["paid_cents"] - refund
        result_orders.append({
            "order_id": oid,
            "customer": order["customer"],
            "paid_cents": order["paid_cents"],
            "refund_cents": refund,
            "net_cents": net,
        })
        customers_total[order["customer"]] = (
            customers_total.get(order["customer"], 0) + net
        )
        totals["paid_cents"] += order["paid_cents"]
        totals["refund_cents"] += refund
        totals["net_cents"] += net

    customers = [
        {"customer": name, "net_cents": customers_total[name]}
        for name in sorted(customers_total)
    ]
    return {"orders": result_orders, "customers": customers, "totals": totals}


def export_bundle(result):
    """Serialize a reconcile result into a simple filename->text bundle."""
    return {"summary.json": json.dumps(result, sort_keys=True)}
